sp_page.css:
html, body { background: #032D42 !important; }
body.sp-can-animate, .sp-page-root, main.body, section.page { background: transparent !important; }
.container, .container-fluid { max-width: none !important; width: 100% !important; padding: 0 !important; margin: 0 !important; }
.sp-row, .row { margin: 0 !important; }
[class*="col-"] { padding: 0 !important; }
sp-widget, .sp-model { display: block; }
